const Board = ({ gameData, socket }) => {
  const [pieces, setPieces] = useState(gameData.board.pieces);
  const [score, setScore] = useState([]);
  const [houseLength, setHouseLength] = useState(0);
  const [gameEnded, setGameEnded] = useState(false);

  const startNewGame = () => {
    // Resetování stavu hry na výchozí hodnoty
    setPieces(gameData.board.pieces);
    setScore([]);
    setHouseLength(0);
    setGameEnded(false);
    // Pokud je potřeba, můžete poslat signál serveru o začátku nové hry
    socket.emit('game:startNewGame');
  };

  return (
    <div className="board-container">
      {gameEnded ? (
        <Ended 
          score={score} 
          houseLength={houseLength} 
          onReturnToApp={() => console.log('Return to main screen')} 
          onNewGame={startNewGame}  // Předání funkce pro novou hru
        />
      ) : (
        <>
          {/* Zbytek herní logiky */}
        </>
      )}
    </div>
  );
};
